  on conflict (node_id, depth, level, format) do update
    set body = excluded.body, generated = excluded.generated, reviewed = excluded.reviewed
    where content.body is distinct from excluded.body
       or content.generated is distinct from excluded.generated
       or content.reviewed is distinct from excluded.reviewed
  returning node_id
)
delete from content
where node_id in (select node_id from master)
  and not (depth = 'research' and level = 'advanced' and format = 'read');

-- Curated, human-reviewed quiz — same set served at every level.
with q as (
  select $lm_quiz$[
    {"id":"q1","type":"mcq","prompt":"The NMDA receptor is called a 'coincidence detector.' It lets calcium into the postsynaptic cell only when:","options":["Glutamate binds, regardless of the postsynaptic cell's state","BOTH glutamate is bound (the presynaptic cell fired) AND the postsynaptic membrane is already depolarized (the postsynaptic cell is active)","The postsynaptic cell is at rest and its channel is plugged by magnesium","Two different neurotransmitters bind at once"],"answerIndex":1,"explanation":"At rest the channel is blocked by a magnesium ion; only depolarization of the postsynaptic cell expels it, and only then can bound glutamate admit calcium. So the receptor signals only when pre- and postsynaptic cells are active TOGETHER — a molecular AND-gate that physically implements Hebb's 'cells that fire together.'"},
    {"id":"q2","type":"mcq","prompt":"Across three days, patient H.M. steadily improved at mirror-drawing while each day insisting he had never done the task. This dissociation shows that:","options":["The hippocampus is where all long-term memories are permanently stored","Procedural (non-declarative) memory can form without the hippocampus, whereas conscious declarative memory requires it","Motor skills are stored in the hippocampus","Working memory depends on the hippocampus"],"answerIndex":1,"explanation":"H.M.'s medial temporal lobes (including the hippocampus) were removed. His skill improved normally (procedural memory, which runs on the striatum and cerebellum) while he formed no conscious memory of the sessions (declarative memory, which needs the hippocampus to consolidate). The two systems were surgically separated in one person."},
    {"id":"q3","type":"mcq","prompt":"'Reconsolidation' refers to the finding that:","options":["A new memory is stabilized once, immediately after learning, and then never changes","Retrieving a consolidated memory returns it to a fragile, editable state, so it must be re-stabilized to persist","Memories are copied from the cortex back into the hippocampus during sleep","Memories decay unless rehearsed out loud"],"answerIndex":1,"explanation":"Nader, Schafe, and LeDoux (2000) showed that recalling an established fear memory and then blocking protein synthesis ERASED it — while the same drug did nothing without retrieval. Recall reopens the memory for editing, which is why memories drift and update over a lifetime, and why eyewitness memory is so malleable."},
    {"id":"q4","type":"mcq","prompt":"During deep slow-wave sleep, the role the hippocampus plays in systems consolidation is to:","options":["Shut down entirely so the cortex can rest","Replay the day's neural firing sequences (e.g., place-cell paths) in compressed form, broadcasting them to the cortex for gradual long-term storage","Erase the day's weak memories by growing new neurons","Manufacture the magnesium that blocks NMDA receptors"],"answerIndex":1,"explanation":"Sleeping rats' place cells re-run the maze sequences they fired while awake, at roughly twenty times speed, and this replay — hippocampal sharp-wave ripples coordinated with cortical slow oscillations and spindles — transfers learning to cortex. It is why sleeping after study beats an all-nighter."},
    {"id":"q5","type":"open","prompt":"State Hebb's rule and explain, step by step, how the NMDA receptor and the events downstream of it (LTP) implement that abstract rule as physical chemistry.","rubric":"Hebb's rule (1949): when one neuron repeatedly takes part in firing another, the connection between them is strengthened — 'cells that fire together, wire together' — and crucially it is LOCAL and unsupervised (a synapse strengthens using only the activity of the two cells it joins). The NMDA receptor implements the coincidence requirement: its channel is plugged by magnesium at rest, so it admits calcium only when glutamate is bound (presynaptic cell fired) AND the postsynaptic membrane is depolarized (postsynaptic cell active) at the same time. The resulting calcium influx, if large and fast, activates kinases (notably CaMKII, which can auto-phosphorylate and stay active), leading to insertion of more AMPA receptors — early-phase LTP, the synapse now stronger. Durable (late-phase) LTP additionally requires new gene transcription (via CREB) and protein synthesis, and ultimately structural change — dendritic spines enlarging or new ones growing. Weak activity instead admits little calcium, activates phosphatases, removes AMPA receptors, and weakens the synapse (LTD). LTP and LTD together let experience sculpt the pattern of synaptic weights that is the memory."},
    {"id":"q6","type":"open","prompt":"The article claims memory is 'not a photograph but a reconstruction.' Explain what reconsolidation is and give one real-world consequence of memory being rebuilt rather than replayed.","rubric":"Reconsolidation: a consolidated long-term memory, when retrieved, briefly returns to a labile state and must be re-stabilized (a process requiring protein synthesis) to persist; interfering in that window can alter or erase it (Nader/Schafe/LeDoux, 2000). Because the memory is physically re-written on each recall, what you remember is really the last time you remembered it, edited in your own hand. Acceptable consequences: (1) eyewitness memory is editable and can incorporate misleading post-event information, with serious implications in the courtroom (Loftus's false/implanted-memory work); (2) memories naturally drift and update to include new information over a lifetime; (3) a therapeutic opening — reactivating a traumatic memory and then updating it with new, safe information (or a drug) during the reconsolidation window may permanently blunt its emotional charge, as pursued in some PTSD treatments."}
  ]$lm_quiz$::jsonb as questions
)
insert into quizzes (node_id, level, questions, generated)
select 'neuroscience/cognitive-neuroscience/learning-and-memory', lvl, q.questions, true
from q, (values ('easy'), ('advanced'), ('expert')) as l(lvl)
on conflict (node_id, level) do update
  set questions = excluded.questions, generated = excluded.generated;
